import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`zoning-envelope`,heroTitle:`Model your zoning envelope in minutes`,heroSubtitle:`Perplexity Computer researches your site's zoning code, calculates buildable massing, and generates a 3D envelope study — automatically.`,inputUrlCta:`Analyze my site`,inputUrlPlaceholder:`e.g. 123 Main St, NYC`,inputUrlPrefill:`Go to {url} and perform a complete zoning envelope analysis for this property or address. 1) Identify the site's zoning district, jurisdiction, and applicable land use regulations — look up the municipal zoning code, zoning map, and any overlay districts. 2) Extract all key dimensional standards: max building height, FAR, lot coverage, front/side/rear setbacks, stepback requirements, sky exposure planes, and any bonus provisions or incentive zoning. 3) Calculate the maximum buildable gross floor area based on lot dimensions and FAR. 4) Generate a 3D massing envelope diagram showing the maximum allowable building volume with setbacks, height limits, and any angular plane or sky exposure constraints clearly labeled. 5) Identify any special conditions — historic overlay, flood zone, landmark adjacency, inclusionary housing bonuses, or transfer of development rights opportunities. 6) Deliver a summary report with: zoning designation, all dimensional constraints in a table, max buildable area calculations, a labeled envelope diagram, and a list of variance or special permit opportunities that could expand the envelope.`,heroOverlaySteps:[`Researching zoning district, setbacks, and height limits for your site`,`Calculating FAR, lot coverage, and maximum buildable area`,`Modeling 3D massing envelope with sky exposure and stepback constraints`,`Zoning summary, envelope diagram, and bonus opportunities — ready to review`],generatingSteps:[`Visiting {url} to identify the site's zoning district and dimensional standards`,`Designing an agent to calculate FAR, setbacks, height limits, and buildable massing`,`Configuring 3D envelope modeling with sky exposure planes and stepback rules`,`Setting up zoning summary report with variance and bonus opportunity analysis`],featureSectionTitle:`From address to buildable envelope`,featureCardTitles:[`Connects to your design stack`,`Outputs you can build from`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Airtable — Computer exports zoning data, envelope diagrams, and massing calculations straight into the tools your team already uses.`,`Zoning constraint tables. FAR and buildable area calculations. 3D massing envelope diagrams. Setback and height limit overlays. Bonus and variance opportunity summaries.`],capabilitySectionTitle:`Your zoning analyst, on autopilot`,capabilitySectionSubtitle:`Enter an address, step away, come back to a complete envelope study.`,capabilityCards:[{title:`Zoning Research`,description:`Computer can look up your site's zoning district, overlay zones, and applicable municipal code — extracting every dimensional standard that shapes your envelope.`},{title:`Envelope Modeling`,description:`Computer can generate 3D massing diagrams showing max height, setbacks, stepbacks, and sky exposure planes — so you see the buildable volume at a glance.`},{title:`FAR Calculations`,description:`Computer can calculate maximum gross floor area, lot coverage, and open space ratios — accounting for base FAR, bonuses, and inclusionary housing incentives.`},{title:`Connect Your Tools`,description:`Computer can export zoning data to Google Sheets, Airtable, Notion, and Google Drive — build workflows across your entire pre-design stack.`},{title:`Remember & Learn`,description:`Computer can remember your project sites, past envelope studies, and preferred jurisdictions — so every new analysis builds on what you've already done.`},{title:`Monitor & Alert`,description:`Computer can track zoning code amendments and re-zone proposals for your sites — and alert you when changes affect your buildable envelope.`}]});export{t as default};
